95: func convertObject(o []byte, projectName string) (*config.Config, error) {
96: 	c := config.Config{
97: 		Coordinate: coordinate.Coordinate{
98: 			Project: projectName,
99: 			Type:    "bucket",
100: 		},
101: 		Type: config.BucketType{},
102: 	}
103: 
104: 	r, err := raw.New(o)
105: 	if err != nil {
106: 		return &c, err
107: 	}
108: 
109: 	id, ok := r.Get(bucketName).(string)
110: 	if !ok {
111: 		return &c, fmt.Errorf("variable %q unreadable", bucketName)
112: 	}
113: 
114: 	// exclude builtin bucket names
115: 	if tools.IsDefault(id) {
116: 		return nil, nil
117: 	}
118: 
119: 	// construct config object with generated config ID
120: 	configID := idutils.GenerateUUIDFromString(id)
121: 	c.Coordinate = coordinate.Coordinate{
122: 		Project:  projectName,
123: 		Type:     "bucket",
124: 		ConfigId: configID,
125: 	}
126: 
127: 	c.OriginObjectId = r.Get(bucketName).(string)
128: 
129: 	r.Delete(bucketName)
130: 
131: 	c.Parameters = map[string]parameter.Parameter{}
132: 	p := r.Parameterize(displayName)
133: 	if p != nil {
134: 		c.Parameters[displayName] = p
135: 	}
136: 
137: 	t, err := r.ToJSON()
138: 	if err != nil {
139: 		return &c, err
140: 	}
141: 	c.Template = template.NewDownloadTemplate(configID, configID, string(jsonutils.MarshalIndent(t)))
142: 
143: 	return &c, nil
144: }

